# deny if a default ServiceAccount has rules bound to it that are not defaults. 
deny[msga] {

    wl := input[_]
	spec_template_spec_patterns := {"RoleBinding", "ClusterRoleBinding"}
	spec_template_spec_patterns[wl.kind]

