        "deletePaths": [sprintf("subjects[%d]", [i])],
        "failedPaths": [sprintf("subjects[%d]", [i])],
        "fixPaths":[],
		"alertScore": 7,
        "alertObject": {
			"k8sApiObjects": [wl]
		}
	}
}

